        ['id' => '140-f-sanhab-plate-export', 'type' => 'feature', 'area' => 'سنهاب', 'title' => 'سنهاب: پلاکِ «۹۹۴ط۵۹ ۷۸»، خروجیِ چندردیفی، اکسل و «PDFِ خروجیِ سایت»',
