        ['id' => '140-i-doc-image-normalize', 'type' => 'improve', 'area' => 'مدارک', 'title' => 'استانداردسازیِ عکسِ مدارک بعد از آپلود بدونِ افتِ خوانایی + جلوگیری از فایلِ ناقص',
