        ['id' => '140-i-inq-perms-settings', 'type' => 'improve', 'area' => 'دسترسی‌ها', 'title' => 'دسترسیِ جدا برای هر نوعِ استعلام (تکی / گروهی) و تنظیماتِ سنهاب',
