        ['id' => '140-f-portal-renewals', 'type' => 'feature', 'area' => 'پنل شرکت‌ها', 'title' => 'زبانه‌ی «تمدیدی‌ها» در پنلِ شرکت‌ها (با اجازه‌ی جدا برای هر کاربر)',
