        ['id' => '140-i-brd-requested', 'type' => 'improve', 'area' => 'بردرو', 'title' => 'وضعیتِ «درخواستِ تمدید ثبت شد» در بردرو و جدا شدنِ تمدید شده‌ها',
         'desc' => 'هر ردیفِ بردرو که درخواستِ تمدید برایش ساخته شده برچسبِ «درخواستِ تمدید ثبت شد» دارد (با فیلتر و شمارنده)؛ بعد از صدور «تمدید شد» می‌شود و فقط در «تمدید شده» دیده می‌شود.'],
        ['id' => '140-i-request-buttons', 'type' => 'improve', 'area' => 'درخواست‌ها', 'title' => 'صدورِ گروهی فقط داخلِ درخواست؛ دانلودِ گروهیِ بیمه‌نامه‌ها در هر درخواست',
         'desc' => 'دکمه‌ی «صدور گروهی» از فهرستِ درخواست‌ها برداشته شد و داخلِ هر درخواست هست. دکمه‌ی «دانلودِ گروهیِ بیمه‌نامه‌های صادره» همیشه در جزئیاتِ درخواست دیده می‌شود (تا صادره‌ای نباشد غیرفعال). کارتِ اطلاعاتِ بالای پنجره‌ی صدور هم مرتب شد و مقدارها روی هم نمی‌افتند.'],
        ['id' => '140-i-group-issue-button', 'type' => 'improve', 'area' => 'درخواست‌ها', 'title' => 'دکمه‌ی «صدور گروهی» در فهرستِ درخواست‌های شرکتی (تمدیدی و بقیه)',
         'desc' => 'در فهرستِ «درخواست‌های شرکتی» برای هر درخواستی که ردیفِ صادرنشده دارد (تمدیدی یا معمولی) دکمه‌ی «صدور گروهی» آمد؛ در جزئیاتِ درخواست هم مثلِ قبل هست. در صفحه‌ی «صدور گروهی» درخواست‌های تمدیدی برچسبِ «تمدیدی» دارند.'],
        ['id' => '140-f-renewals-bordereau-merge', 'type' => 'feature', 'area' => 'تمدید', 'title' => 'ادغامِ بردروی پاسارگاد با «اعلام تمدید» و صفحه‌ی «تمدید شده‌ها»',
         'desc' => 'ردیف‌های بردرو هم در «اعلام تمدید» آمدند با برچسبِ ورودی («بردرو»، «پنل» یا «پنل + بردرو» برای بیمه‌نامه‌ای که هر دو جا هست) و فیلترِ «ورودی». بعد از «درخواستِ تمدید»، روی همان ردیف (و در جزئیاتِ درخواستِ قبلی و بردرو) نوشته می‌شود «با نامه‌ی … در تاریخ … درخواستِ تمدید … ثبت شد» و وقتی صادر شد «… و با بیمه‌نامه‌ی شماره‌ی … تمدید شد» با برچسبِ «تمدید شد»؛ این ردیف‌ها از «اعلام تمدید» به زبانه‌ی «تمدید شده‌ها» می‌روند. دکمه‌ی «لغوِ انتخاب» آمد و بعد از ثبتِ درخواست انتخاب‌ها خودکار لغو می‌شوند. بارگذاریِ اکسل و الحاقیه‌های بردرو مثلِ قبل از صفحه‌ی بردرو است (دکمه‌اش در «اعلام تمدید» هست).'],
        ['id' => '140-f-liability-14b', 'type' => 'feature', 'area' => 'صدور', 'title' => 'تعهدِ مالیِ ثالث ۱۲ و ۱۴ میلیارد ریال و سقفِ قابلِ انتخاب برای کارکنان و شرکت‌ها',
         'desc' => 'مبالغِ ۱۲٬۰۰۰٬۰۰۰٬۰۰۰ و ۱۴٬۰۰۰٬۰۰۰٬۰۰۰ ریال اضافه شد. در «مرکز صدور ← تنظیماتِ صدور» بیشترین مبلغی که کارکنان (ربات، مینی‌اپ، ثبتِ دستی) و شرکت‌ها (پنلِ ما و پنلِ شرکت‌ها) می‌بینند و ثبت می‌کنند تعیین می‌شود؛ پیش‌فرض کارکنان ۱۰ میلیارد و شرکت‌ها ۱۴ میلیارد ریال.'],
        ['id' => '140-x-car-name-dup', 'type' => 'fix', 'area' => 'صدور', 'title' => 'تکرارِ نامِ خودرو (مثلاً «سمند سورن · سمند سورن»)',
         'desc' => 'در صادره‌ها، در حالِ صدور، جزئیاتِ درخواست، پنلِ شرکت‌ها و فهرست‌های دیگر نامِ خودرو و تیپ وقتی یکی یا داخلِ هم بودند دوبار نوشته می‌شد؛ حالا یک بار می‌آید.'],
        ['id' => '140-x-edit-sync-issue-panel', 'type' => 'fix', 'area' => 'صدور', 'title' => 'ویرایشِ درخواست (کلی یا یک ردیف) در پنلِ صدور هم دیده می‌شود',
         'desc' => 'بعد از تغییرِ مالک/بیمه‌گذار از بالای درخواست یا روی چند ردیف، و تغییرِ تیپ و مشخصاتِ ردیف، «اطلاعات برای صدور» هم با همان مقادیرِ تازه هم‌سان می‌شود و پنلِ صدور اطلاعاتِ قبلی را نشان نمی‌دهد. در درخواست‌های کارکنان هم پنلِ صدور آخرین اطلاعاتِ پرونده را نشان می‌دهد. ردیف‌های صادرشده دست نمی‌خورند.'],
        ['id' => '140-f-site-slips', 'type' => 'feature', 'area' => 'مالی', 'title' => 'فیشِ ساختِ سامانه وقتی فیش‌های بیمه‌نامه با اقساطِ قرارداد فرق دارد',
         'desc' => 'در «مرکز صدور» دکمه‌ی «تنظیمِ فیش‌ها» آمد (جدا برای صدورِ کارکنان و شرکتی) و در تعریفِ هر شرکت هم همین گزینه هست (یا پیش‌فرضِ کلی). با «فیش با سامانه»، اگر فیش‌های داخلِ فایلِ بیمه‌نامه (تعداد، مبلغ، سررسید یا شماره‌ی قرارداد) با اقساطِ قرارداد یکی نبود، اقساط طبقِ قرارداد ثبت می‌شود و سامانه برای هر قسط یک فیشِ PDF (بیمه‌گذار، بیمه‌نامه، سررسید، مبلغ به عدد و حروف، حساب و بانک، جدولِ اقساط) در پوشه‌ی «فیش‌های پرداختی» همان بیمه‌نامه می‌سازد؛ گزینه‌ی دیگر وقتی فیشی در فایل نبود هم فیش می‌سازد. فیش‌های اصلیِ بیمه‌نامه، اقساطِ فعلی و دریافتی‌ها دست نمی‌خورند؛ برای یک بیمه‌نامه هم در «مالی و روشِ پرداخت» می‌شود همین را انتخاب کرد. پیش‌فرض همان روشِ قبلی است.'],
        ['id' => '140-f-bordereau-fields', 'type' => 'feature', 'area' => 'بردرو', 'title' => 'بردروی پاسارگاد: پوشش‌ها، ارزش، تعهد، پلاکِ کادری و اطلاعاتِ بیمه‌گذار از اکسل',
         'desc' => 'از اکسلِ ورودی پوشش‌های بدنه (از «نوع پوشش اضافی» با سقف‌ها)، ارزشِ خودرو، تعهدِ مالیِ ثالث، پلاک (در کادرِ پلاکِ خودمان)، نام و کد ملی/شناسه‌ی بیمه‌گذار، حقیقی یا حقوقی، کد اقتصادی، بیمه‌نامه‌ی قبلی و انقضایش، سال‌های عدمِ خسارت، تخفیف، ظرفیت و سیلندر برداشته و در جدول، جزئیات و خروجیِ اکسل نشان داده می‌شود. ردیف‌های قبلاً واردشده دست نمی‌خورند.'],
        ['id' => '140-f-bordereau-change-endorsement', 'type' => 'feature', 'area' => 'بردرو', 'title' => 'الحاقیه‌ی تغییرِ اطلاعات روی هر ردیفِ بردرو',
         'desc' => 'در الحاقیه‌ی «تغییر» خانه‌هایی مثلِ پلاک، بیمه‌گذار، کد ملی، حقیقی/حقوقی، ارزش، تعهد، پوشش‌ها، رنگ، شاسی و موتور را می‌شود عوض کرد. ردیف با آخرین اطلاعاتِ الحاقیه‌ها نمایش داده می‌شود، برچسبِ «تغییر کرد» می‌گیرد و در جزئیات اطلاعاتِ اولیه (خط‌خورده) کنارِ مقدارِ تازه دیده می‌شود. درخواستِ تمدید با همین اطلاعاتِ آخر ساخته می‌شود.'],
        ['id' => '140-f-renewal-company-letter', 'type' => 'feature', 'area' => 'تمدید', 'title' => 'درخواستِ تمدید: شرکتِ درخواست‌دهنده، نامه، نوعِ «تمدیدی» و انتخابِ پوشش‌ها',
         'desc' => 'در پنجره‌ی «درخواستِ تمدید» شرکتِ درخواست‌دهنده انتخاب می‌شود (یا همان شرکتِ هر ردیف)، نامه بارگذاری و در بایگانیِ همان درخواست ذخیره می‌شود و توضیح هم می‌شود نوشت. درخواست در «درخواست‌های شرکتی» با برچسبِ «تمدیدی» می‌نشیند؛ مشخصاتِ خودرو، بیمه‌گذار و مدارکِ موجود روی ردیف می‌آید و در پنلِ صدور دیده می‌شود. با گزینه‌ی «پوشش‌ها و تعهد» می‌شود همان مقادیرِ قبلی یا پیش‌فرضِ شرکت را انتخاب کرد؛ بعداً هم روی هر ردیف قابلِ ویرایش است.'],
        ['id' => '140-f-company-doc-read', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'تنظیمِ «خواندنِ خودکارِ مدارک» برای هر شرکت',
         'desc' => 'در تعریفِ شرکت گزینه‌ی «مدارکِ این شرکت خودکار خوانده شود» آمد. اگر برداشته شود، مدارکِ بارگذاری‌شده‌ی آن شرکت فقط ذخیره می‌شوند و اطلاعاتی از آن‌ها استخراج نمی‌شود (دکمه‌ی خواندنِ دستی همچنان کار می‌کند). پیش‌فرض برای شرکت‌های فعلی روشن است.'],
        ['id' => '140-f-renewal-requests', 'type' => 'feature', 'area' => 'تمدید', 'title' => 'درخواستِ تمدید از «اعلام تمدید» و «بردروی پاسارگاد» با مدارکِ قبلی',
         'desc' => 'روی هر ردیفِ «اعلام تمدید» دکمه‌ی تمدید و برای انتخاب‌شده‌ها «درخواستِ تمدید (صدورِ تازه)» آمد؛ در بردرو هم «درخواستِ تمدید». برای هر ردیف درخواستِ صدور برای همان شرکت با همان مشخصات ساخته می‌شود (ردیف‌های یک شرکت در یک درخواست) و کارت/سند/فاکتور و خودِ بیمه‌نامه‌ی قبلی، اگر در سامانه باشد، مستقیم روی درخواست می‌نشیند. بدنه: «بدونِ خسارت» = مدرکِ تازه‌ی «گزارش عدم خسارت» لازم و بازدید نه؛ «خسارت داشته» = بازدیدِ سلامت دوباره لازم. ثالث: همان مدارکِ قبلی. برای بیمه‌نامه‌های کارکنان فرمِ «ثبتِ دستیِ درخواستِ کارکنان» با همان اطلاعات باز می‌شود. اگر برای همان خودرو درخواستِ بازِ دیگری باشد ساخته نمی‌شود. خروجیِ اکسل در هر دو بخش مثلِ قبل هست.'],
        ['id' => '140-f-vr-type-access', 'type' => 'feature', 'area' => 'دسترسی‌ها', 'title' => 'دسترسی به انواعِ گزارشِ بازدید برای هر کاربر',
         'desc' => 'در پنجره‌ی «دسترسی‌ها»ی هر کاربر بخشِ «انواعِ گزارشِ بازدید» آمد: «همه‌ی انواع» یا «فقط انواعِ انتخاب‌شده». کاربرِ محدود فقط همان نوع‌ها را می‌سازد و در فهرستِ گزارش‌ها می‌بیند، حتی با دسترسیِ سفارشیِ کامل.'],
        ['id' => '140-i-request-bg-upload', 'type' => 'improve', 'area' => 'درخواست‌ها', 'title' => 'ثبتِ درخواست بی‌معطلی؛ مدارک در پس‌زمینه با نوارِ پیشرفت',
         'desc' => 'در «ثبتِ دستیِ درخواستِ کارکنان» و «ثبتِ کاملِ درخواستِ دستیِ شرکت»، درخواست همان لحظه ثبت می‌شود و مدارک در پس‌زمینه (مثلِ آپلودِ آهنگ‌ها) با نوارِ پیشرفتِ پایینِ صفحه بارگذاری می‌شوند؛ پنجره را می‌شود بست و کار ادامه دارد.'],
        ['id' => '140-i-checklist-buttons', 'type' => 'improve', 'area' => 'درخواست‌ها', 'title' => 'دکمه‌های بارگذاریِ مدارکِ هر ردیف مرتب و خوانا',
         'desc' => 'در چک‌لیستِ مدارکِ ردیف‌های شرکتی (پنلِ ما و پنلِ شرکت‌ها) عنوانِ هر خانه می‌شکند و انتخابِ نوع، نامِ مدرک و دکمه‌های بارگذاری زیرِ هم در عرضِ همان خانه می‌نشینند و دیگر روی خانه‌ی کناری نمی‌افتند.'],
        ['id' => '140-x-inquiry-intro-nid', 'type' => 'fix', 'area' => 'استعلامات', 'title' => 'استعلامِ نام/کد پستی در ثبتِ درخواستِ کارکنان، کد ملی را برنمی‌داشت',
         'desc' => 'وقتی درخواست روی معرفی‌نامه ثبت می‌شد، کد ملیِ صاحبِ معرفی‌نامه به استعلام نمی‌رسید و «اول کد ملی و تاریخ تولد را وارد کنید» می‌آمد. حالا برای خودِ پرسنل کد ملیِ معرفی‌نامه و برای بستگان کد ملیِ خودِ بیمه‌گذار با تاریخ تولدِ او استعلام می‌شود و پیام می‌گوید کدام خانه کم است. پیام‌های تأییدِ «حذف از تاریخچه» و مشابه هم با پاپ‌آپِ خودِ سایت آمد.'],
        ['id' => '140-f-registry-in-forms', 'type' => 'feature', 'area' => 'پرونده‌ها', 'title' => 'پیشنهادِ اطلاعات و مدارکِ موجود هنگامِ ثبتِ درخواستِ تازه',
         'desc' => 'در «ثبتِ کاملِ درخواستِ دستیِ شرکت»، «افزودنِ پلاک» به یک درخواست، «ثبتِ دستیِ درخواستِ کارکنان» و فرمِ درخواستِ پنلِ شرکت‌ها، با نوشتنِ پلاک، شماره شاسی یا موتور، اگر همین خودرو قبلاً در سامانه بوده کادری می‌آید: مشخصات، مالک، آخرین بیمه‌نامه و درخواست‌های باز. «بیار اطلاعات» نام/تیپ/شاسی/موتور و انقضای بیمه‌نامه‌ی قبلی را (فقط خانه‌های خالی) پر می‌کند و مدارکِ تیک‌خورده (کارت، سند، فاکتور، بیمه‌نامه‌ی قبلی) بعد از ثبت روی ردیفِ تازه کپی و نام‌گذاری می‌شوند. در فرمِ کارکنان با کد ملی (یا نام) هم اطلاعاتِ شخص (نام، کد پرسنلی، شرکت، موبایل، کد پستیِ استعلام‌شده، نشانی) پیشنهاد می‌شود. پنلِ شرکت‌ها فقط خودروها و مدارکِ شرکت‌های خودش را می‌بیند؛ فایل‌های اصلی دست نمی‌خورند.'],
        ['id' => '140-f-issue-panel', 'type' => 'feature', 'area' => 'صدور', 'title' => 'پنلِ صدور روی هر ردیفِ شرکتی و کارکنان',
         'desc' => 'دکمه‌ی «پنل صدور» روی ردیف‌های جزئیاتِ درخواستِ شرکت، فهرستِ «در حال صدور» و فهرستِ درخواست‌های کارکنان آمد. پاپ‌آپی باز می‌شود با بیمه‌گذار، مالک، ذینفع، مشخصاتِ کاملِ خودرو و اطلاعاتِ درخواست؛ با زدن روی هر خانه همان مقدار کپی می‌شود (کپیِ هر بخش و کپیِ همه هم هست). کنارش همه‌ی مدارک (نامه، کارت/سند، بیمه‌نامه‌ی قبلی، عکس‌های بازدید و …) یکی‌یکی نمایش داده می‌شوند (با کلیدهای چپ/راست) و دکمه‌های «ثبت صدور» و «پرونده‌ی خودرو» هم همان‌جاست.'],
        ['id' => '140-f-company-request-defaults', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'پیش‌فرضِ پوشش‌های بدنه و تعهدِ ثالث در شرکت، درخواست و ورود از نامه',
         'desc' => 'در تعریفِ شرکت کادرِ «پیش‌فرضِ درخواست‌های این شرکت» آمد (تعهدِ مالیِ ثالث و پوشش‌های بدنه). در جزئیاتِ هر درخواست دکمه‌ی «پیش‌فرضِ پوشش و تعهد» آمد: فقط برای ردیف‌های تازه، پر کردنِ ردیف‌های خالی، یا عوض کردنِ همه‌ی ردیف‌های صادرنشده. در «ورود ردیف‌ها از نامه» هم پیش‌فرض تعیین می‌شود و روی ردیف‌هایی می‌نشیند که در نامه تعهد یا پوشش ندارند. ثبتِ دستی، افزودنِ ردیف و ردیف‌هایی که شرکت در پنلش می‌سازد هم از همین پیش‌فرض (درخواست، وگرنه شرکت) پر می‌شوند؛ هر ردیف مثلِ قبل جدا قابلِ ویرایش است و ردیفِ صادرشده تغییر نمی‌کند.'],
        ['id' => '140-f-company-inspection-upload', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'بازدیدِ ارسالیِ شرکت‌ها (زیپ، RAR، پوشه) روی ردیف‌های بدنه',
         'desc' => 'در خانه‌ی «گزارش و عکس‌های بازدید» هر ردیفِ بدنه (پنلِ ما و پنلِ شرکت‌ها) دکمه‌های «زیپ/RAR/عکس» و «پوشه» آمد: زیپ داخلِ پوشه‌ی بازدید باز می‌شود، RAR همان‌طور نگه داشته می‌شود و پوشه یا چند عکس در مرورگر یک زیپ می‌شود. وقتی بازدید رسید، ردیف «آماده‌ی صدور (گزارش بازدید)» می‌شود و گزارشِ بازدید دیگر کسریِ شرکت حساب نمی‌شود (گزارش را خودمان در سایت می‌سازیم). با «ساخت گزارش بازدید»، عکس‌های بازدیدِ همان ردیف خودکار در گزارش می‌آیند (همه تیک‌خورده، قابلِ برداشتن).'],
        ['id' => '140-f-rows-text-only-missing', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'فهرستِ متنیِ درخواست: «همه‌ی ردیف‌ها» یا «فقط دارای کسری»',
         'desc' => 'در «فهرست متنی ریز درخواست» دو دکمه آمد: همه‌ی ردیف‌ها (مثلِ قبل) یا فقط ردیف‌هایی که هنوز مدرکی کم دارند، تا متنِ کوتاهِ کسری‌ها را برای شرکت کپی کنید. انتخابِ آخر در همان مرورگر می‌ماند.'],
        ['id' => '140-i-row-other-docs-multi', 'type' => 'improve', 'area' => 'شرکت‌ها', 'title' => 'چند «مدرکِ دیگر» با نام‌های جدا روی هر ردیف',
         'desc' => 'در خانه‌ی «مدرکِ دیگر» هر ردیف (پنلِ ما و پنلِ شرکت‌ها) می‌شود یک یا چند فایل را با هم انتخاب کرد: با نامِ نوشته‌شده (چندتایی: «نام ۱»، «نام ۲») یا اگر نامی ننوشتید، با نامِ خودِ فایل؛ و هر بار با نامِ تازه مدرکِ دیگری اضافه کرد.'],
        ['id' => '140-f-vehicle-registry', 'type' => 'feature', 'area' => 'پرونده‌ها', 'title' => 'پرونده‌ی هر پلاک (خودروها)',
         'desc' => 'در «بیمه با ما ← پرونده‌ها و بردرو ← پرونده‌ی خودروها» هر خودرو (یکی‌شده بر اساسِ پلاک و شماره شاسی از درخواست‌های شرکتی، وارداتی، کارکنان و بردرو) یک پرونده دارد: مشخصات، مالک‌ها، همه‌ی بیمه‌نامه‌ها و درخواست‌های باز، مدارک، اقساط، الحاقیه‌ها و یادداشت؛ با جستجو در همه‌ی ستون‌ها، فیلترِ شرکت/نوع/منبع/انقضا، اکسلِ فهرست و گزارشِ PDFِ زیبا. تصویرِ خودرو بر اساسِ نوع کشیده می‌شود (سواری، کامیون برای بارکش، وانت، اتوبوس، موتور و …) و متحرک است؛ برای هر مدل می‌شود عکسِ واقعی هم گذاشت. شرکت‌ها هم در پنلِ خودشان زبانه‌ی «خودروها» را فقط برای خودروهای خودشان می‌بینند.'],
        ['id' => '140-f-personnel-registry', 'type' => 'feature', 'area' => 'پرونده‌ها', 'title' => 'پرونده‌ی پرسنل',
         'desc' => 'هر پرسنل پرونده دارد: شرکتِ فعلی و سابقه‌ی جابه‌جایی با تاریخ، عکس، مشخصات، خانواده، خودروها، بیمه‌های اتومبیل، عمر و درمان تکمیلی، اقساطِ معوق و مدارک، با گزارشِ PDF و اکسل. با بارگذاریِ لیستِ پرسنلیِ هر شرکت، جابه‌جایی‌ها با تاریخ ثبت و افرادِ تازه ساخته می‌شوند (پیش‌نمایش قبل از ثبت؛ کد ملیِ نامعتبر پذیرفته نمی‌شود).'],
        ['id' => '140-f-bordereau', 'type' => 'feature', 'area' => 'پرونده‌ها', 'title' => 'بردروی پاسارگاد (جدا از مالی و صادره‌ها)',
         'desc' => 'اکسلِ بردروی پاسارگاد بارگذاری می‌شود (پیش‌نمایش، سپس ثبت؛ بارگذاریِ دوباره ردیف‌ها را به‌روز می‌کند). فهرستِ کلی و شرکت‌به‌شرکت با مشخصاتِ خودرو، تاریخِ تمدید و وضعیتِ تمدیدشده، جستجو در همه‌ی ستون‌ها، فیلترها، الحاقیه (اضافی، برگشتی، تغییر، تمدید، فسخ)، یادداشت و خروجیِ اکسل و PDF برای هر شرکت و کل. برای هر ردیف پوشه‌ی بایگانی با همان نام‌گذاری بر اساسِ تاریخ ساخته می‌شود. داده‌ها در پرونده‌ی خودرو و پرسنل دیده می‌شوند ولی به مالی و صادره‌ها کاری ندارند.'],
        ['id' => '140-f-inquiry-postal-limit-reset', 'type' => 'feature', 'area' => 'استعلامات', 'title' => 'سقفِ روزانه برای کد پستی و صفر کردنِ سقفِ یک کد ملی / کد پستی',
         'desc' => 'هر کد پستی هم در روز حداکثر ۲ بار استعلام می‌شود (در تنظیماتِ استعلامات قابلِ تغییر). در همان تنظیمات کادرِ «سقفِ امروزِ یک کد ملی یا کد پستی» آمد: شمارشِ امروز را نشان می‌دهد و با «صفر کردن» دوباره اجازه‌ی استعلام می‌دهد.'],
        ['id' => '140-i-inquiry-persian-names', 'type' => 'improve', 'area' => 'استعلامات', 'title' => 'نام‌های برگشتی از استعلام فارسیِ یکدست می‌شوند',
         'desc' => 'نام، نام خانوادگی و نامِ پدرِ برگشتی از سامانه که با «ي» و «ك» عربی، اعراب یا فاصله‌های نامرتب می‌آمد، قبل از نمایش و ذخیره به فارسیِ یکدست تبدیل می‌شود (نتیجه‌های قبلی هم هنگامِ نمایش اصلاح می‌شوند).'],
        ['id' => '140-f-inquiry-known-postal', 'type' => 'feature', 'area' => 'استعلامات', 'title' => 'کد پستیِ استعلام‌شده‌ی قبلی خودکار نوشته می‌شود',
         'desc' => 'در مینی‌اپ (اطلاعاتِ هویتی) و فرمِ ثبتِ دستیِ درخواستِ کارکنان در پنل، اگر برای همان کد ملی قبلاً کد پستیِ تأییدشده استعلام شده باشد، خانه‌ی کد پستی خودکار پر می‌شود با پیامِ «قبلاً استعلام و تأیید شده»؛ کاربر می‌تواند کدِ تازه بنویسد.'],
        ['id' => '140-i-legal-no-inquiry', 'type' => 'improve', 'area' => 'شرکت‌ها', 'title' => 'ثبتِ شرکت بدونِ استعلامِ شناسه‌ی ملی',
         'desc' => 'در فرمِ ثبت و ویرایشِ شرکت دکمه‌ی «استعلام از سامانه» برداشته شد و مشخصاتِ ثبتی دستی وارد می‌شود. در بخشِ استعلامات هم «شخص حقوقی» دیگر برای استعلامِ تازه نیست (تاریخچه‌ی قبلی سرِ جایش است).'],
        ['id' => '140-f-inquiry-daily-limits', 'type' => 'feature', 'area' => 'استعلامات', 'title' => 'سقفِ روزانه‌ی استعلام برای هر کد ملی و هر کاربر',
         'desc' => 'هر کد ملی در روز حداکثر ۲ بار استعلام می‌شود (همه‌ی کاربران و مینی‌اپ روی هم؛ در «استعلامات ← تنظیمات» قابلِ تغییر، ۰ = بدونِ سقف). هر کاربرِ پنل هم سقفِ روزانه دارد: پیش‌فرضِ کلی در تنظیماتِ استعلامات و عددِ اختصاصیِ هر نفر در فرمِ کاربر (خالی = پیش‌فرض، ۰ = بدونِ سقف). در فهرستِ کاربران مصرفِ امروز / سقفِ هر نفر دیده می‌شود و با دکمه‌ی «صفر کردن» در فرمِ کاربر شمارشِ امروزش از نو شروع می‌شود. نتیجه‌های ذخیره‌شده‌ی قبلی سقف را مصرف نمی‌کنند، استعلامی که منتظرِ کپچا مانده دوباره شمرده نمی‌شود و مدیر کل سقفِ کاربری ندارد.'],
        ['id' => '140-x-inquiry-captcha-always-wrong', 'type' => 'fix', 'area' => 'استعلامات', 'title' => 'کپچای استعلام همیشه «اشتباه» گفته می‌شد',
         'desc' => 'کدِ تصویرِ امنیتی درست بود ولی سامانه همیشه «نام کاربری، رمز یا کپچا اشتباه است» می‌گفت؛ چون پیش از ورود یک بار وضعیتِ نشست بررسی می‌شد و همین کار کپچای سامانه را عوض می‌کرد. حالا از لحظه‌ای که تصویر نمایش داده می‌شود تا زدنِ کد هیچ درخواستی (بررسیِ وضعیت، cron یا استعلامِ دیگر) به سامانه نمی‌رود، بعد از کدِ اشتباه همان تصویرِ تازه‌ی سامانه نشان داده می‌شود و خانه‌ی کد حروف را هم می‌پذیرد.'],
        ['id' => '140-x-miniapp-inquiry-server-error', 'type' => 'fix', 'area' => 'مینی‌اپ', 'title' => '«خطا در سرور» در استعلامِ مینی‌اپ',
         'desc' => 'استعلامِ نام و کد پستی در مینی‌اپ یک درخواستِ طولانی بود که روی بعضی سرورها/مرورگرها وسطِ راه قطع می‌شد و «خطا در سرور» می‌داد. حالا مثلِ پنل، استعلام شروع می‌شود و وضعیتش هر چند ثانیه پیگیری می‌شود؛ بعد از زدنِ کپچا هم همین‌طور ادامه پیدا می‌کند. اگر استعلام به هر دلیلی انجام نشود، پیامِ روشن می‌آید و اطلاعات را می‌شود دستی نوشت.'],
        ['id' => '140-f-panel-jalali-calendar', 'type' => 'feature', 'area' => 'پنل', 'title' => 'تقویمِ شمسی برای همه‌ی خانه‌های تاریخ در پنل‌ها',
         'desc' => 'همان تقویمِ زیبای مینی‌اپ (با انتخابِ روز، ماه و سال) حالا در پنلِ مدیر، کاربران و پنلِ شرکت‌ها برای همه‌ی خانه‌های تاریخ باز می‌شود: با کلیک روی خانه تقویم کنارش باز می‌شود و تایپِ دستی هم مثلِ قبل ممکن است (تقویم با تایپ همگام می‌شود). دکمه‌های «امروز» و «پاک کردن» هم دارد؛ اگر خانه ساعت هم دارد فقط تاریخ عوض می‌شود. در مینی‌اپ تاریخ فقط از روی تقویم انتخاب می‌شود (صفحه‌ی مدیریتِ مینی‌اپ هم همین‌طور شد).'],
        ['id' => '140-x-jalali-leap-1403', 'type' => 'fix', 'area' => 'تقویم', 'title' => 'کبیسه‌ی ۱۴۰۳ و ۱۴۰۴ در تقویم و سررسیدِ اقساط',
         'desc' => 'تقویمِ مینی‌اپ و محاسبه‌ی طولِ اسفند در ساختِ اقساط، ۱۴۰۴ را کبیسه و ۱۴۰۳ را عادی حساب می‌کرد (برعکسِ تقویمِ رسمی). حالا با چرخه‌ی ۳۳ساله درست است: ۳۰ اسفندِ ۱۴۰۳ قابلِ انتخاب است و ۳۰ اسفندِ ۱۴۰۴ نه. اقساطِ ثبت‌شده‌ی قبلی دست نمی‌خورند.'],
        ['id' => '140-f-contract-audience', 'type' => 'feature', 'area' => 'قراردادها', 'title' => 'یک شماره قرارداد با اقساطِ جدا برای کارکنان و شرکت‌ها',
         'desc' => 'در فرمِ قرارداد «برای چه کسانی» آمد (همه / فقط کارکنان / فقط شرکت‌ها). حالا می‌شود دو قراردادِ ۵۰۵۱ داشت: «۵۰۵۱ کارکنان» با ۱۲ قسط و «۵۰۵۱ شرکتی» با ۹ قسط. در صفحه‌ی قراردادها کادرِ تازه‌ی «شرکت‌ها (پیش‌فرض)» هم آمد تا شرکت‌هایی که قراردادِ جداگانه ندارند طبقِ قراردادِ شرکتی حساب شوند. شماره‌ی قراردادِ داخلِ بیمه‌نامه با قراردادِ همان گروه مقایسه می‌شود. قراردادها و اقساطِ قبلی تغییری نمی‌کنند.'],
        ['id' => '140-i-word-pdf-fidelity', 'type' => 'improve', 'area' => 'صورتحساب و قالب‌ها', 'title' => 'تبدیلِ Word به PDF دقیقاً مثلِ طراحیِ Word (سربرگ، کادرها، شکل‌ها)',
         'desc' => 'موتورِ تبدیلِ Word به PDF (صورتحساب‌ها، رسید و فیشِ بیمه‌ی عمر، پیش‌نمایشِ قالب) بازنویسی شد: سربرگ و پاصفحه‌ی تصویری، شکل‌های منحنی و رنگِ تدریجی، کادرهای متنی (حتی چرخیده)، عکس‌های بریده‌شده، واترمارک و سربرگِ قالب‌های قدیمی، سربرگِ جدا برای صفحه‌ی اول، کادر و رنگِ صفحه، Tab با نقطه‌چین، کادرِ پاراگراف، شماره‌ی صفحه و لایه‌ها (پشت/جلوی متن) مثلِ Word رسم می‌شوند و متن‌هایی مثلِ {{ name }} در متنِ راست‌چین وارونه نمی‌شوند. اگر در Word گزینه‌ی «جاسازیِ قلم‌ها در فایل» روشن باشد یا قلم در «تنظیماتِ گزارشِ بازدید ← قلم‌ها» بارگذاری شده باشد، همان قلم در PDF می‌آید. اگر LibreOffice روی سرور باشد همچنان اول از آن استفاده می‌شود.'],
        ['id' => '140-f-pdf-to-image-tool', 'type' => 'feature', 'area' => 'ابزارها', 'title' => 'تبدیلِ PDF به عکس در ابزارها',
         'desc' => 'در «ابزارها» تبدیلِ PDF به عکس (همه یا صفحه‌های انتخابی، JPG یا PNG) در خودِ مرورگر انجام می‌شود: یک صفحه = یک عکس، چند صفحه = فایلِ زیپ. چیزی به سرور فرستاده نمی‌شود.'],
        ['id' => '140-x-inquiry-buttons-after-login', 'type' => 'fix', 'area' => 'استعلامات', 'title' => 'دکمه‌های استعلام بعد از واردکردنِ کپچا کار نمی‌کردند',
         'desc' => 'بعد از ورودِ موفق با کپچا، دکمه‌های استعلام دیگر پاسخ نمی‌دادند. درست شد. نام کاربری و رمزِ سامانه فقط از «تنظیمات» گرفته می‌شود و هیچ کاربری آن را نمی‌بیند. جزئیاتِ مرحله‌به‌مرحله فقط برای مدیر کل نمایش داده می‌شود و بقیه‌ی کاربران و مینی‌اپ فقط نتیجه را می‌بینند.'],
        ['id' => '140-x-security-own-uploads', 'type' => 'fix', 'area' => 'امنیت', 'title' => 'بارگذاری‌های خودِ کارکنان رخدادِ بحرانی حساب نمی‌شود',
         'desc' => 'در «سپرِ امنیتی» فایلِ ردشده‌ای که یکی از کاربرانِ واردشده‌ی پنل فرستاده بود (مثلاً فرمتِ نامعتبر) به‌عنوانِ «آپلودِ فایلِ خطرناک» و رخدادِ بحرانی ثبت می‌شد. حالا این موارد با سطحِ «کم» و عنوانِ «فایلِ ردشده» ثبت می‌شوند و رخدادهای قبلیِ مشابه یک بار اصلاح شدند. بررسیِ «محافظِ پوشه‌ها» هم پوشه‌ی حذف‌شده‌ی اسکریپت‌های پایتون را دیگر نمی‌خواهد و بررسیِ «اجرای برنامه از PHP» با نیازِ فعلیِ سایت هماهنگ شد.'],
        ['id' => '140-i-word-pdf-everywhere', 'type' => 'improve', 'area' => 'صورتحساب و قالب‌ها', 'title' => 'PDFِ صورتحساب، رسید و فیش بدونِ LibreOffice',
         'desc' => 'هر جا Word پر و بایگانی می‌شد (صورتحساب، پیش‌نمایشِ قالب، رسید و فیشِ قسطِ بیمه‌ی عمر و ربات) PDF هم دوباره ساخته و کنارِ Word بایگانی می‌شود، حتی اگر روی سرور LibreOffice نباشد.'],
        ['id' => '140-i-inquiry-captcha-every-user', 'type' => 'improve', 'area' => 'استعلامات', 'title' => 'کپچای سامانه برای هر کاربر، زیرِ همان فیلدها',
         'desc' => 'نام کاربری و رمزِ سامانه‌ی پاسارگاد فقط یک بار در «استعلامات ← تنظیمات» وارد می‌شود. اگر نشستِ سامانه بسته باشد، هر کاربری که استعلام می‌زند (استعلامِ تکی، گروهی، دکمه‌های فرمِ ثبتِ درخواست و مینی‌اپ) کدِ تصویرِ امنیتی را زیرِ همان فیلدهایش می‌بیند؛ با زدنش ورود خودکار انجام و همان استعلام ادامه پیدا می‌کند. نشست تا یک ساعت (قابلِ تنظیم) بعد از آخرین استعلام باز نگه داشته می‌شود و بعد رها می‌شود. ابزارِ آزمایشیِ «ocr-lab» (وابسته به پایتون و tesseract) از سایت برداشته شد.'],
        ['id' => '140-f-inquiries-section', 'type' => 'feature', 'area' => 'استعلامات', 'title' => 'بخشِ تازه‌ی «استعلامات»: شخص حقیقی، کد پستی و شخص حقوقی',
         'desc' => 'منوی «استعلامات» با چهار نوع: شخص حقیقی (نام، نام خانوادگی، نام پدر و جنسیت با کد ملی و تاریخ تولد)، شخص حقیقی + کد پستی، فقط کد پستی (تأیید در سامانه‌ی املاک و اسکان از راهِ سامانه‌ی پاسارگاد) و شخص حقوقی (s.api.ir). استعلامِ تکی با نوارِ پیشرفتِ گام‌ها، استعلامِ گروهی با اکسل (اکسلِ نمونه، پیش‌نمایش، اجرای ردیف‌به‌ردیف با امکانِ ادامه/لغو/تکرارِ ناموفق‌ها و خروجیِ اکسلِ نتیجه)، و تاریخچه با جستجو و فیلتر و خروجی. مدیر کل جزئیاتِ کامل (تایم‌لاینِ گام‌ها، وضعیتِ فرمِ سامانه و صفحه‌ی واقعیِ سامانه در هر گام) را می‌بیند و بقیه فقط نتیجه را. در «دسترسی‌ها» برای هر کاربر استعلامِ تکی، گروهی، تاریخچه، حذف و خروجی جدا تعیین می‌شود. تنظیمات (ورود به سامانه با کپچا، رمزِ رمزنگاری‌شده، مکثِ بینِ گام‌ها، اعتبارِ نتیجه‌ی قبلی، سقفِ روزانه، cron برای نگه‌داشتنِ نشست و ادامه‌ی گروهی در پس‌زمینه) فقط دستِ مدیر کل است. چون نشستِ سامانه یکی است، استعلام‌ها پشتِ سرِ هم در صف اجرا می‌شوند و نتیجه‌ی تازه تا چند روز دوباره استفاده می‌شود.'],
        ['id' => '140-f-inquiry-forms-miniapp', 'type' => 'feature', 'area' => 'استعلامات', 'title' => 'استعلامِ نام و کد پستی در ثبتِ درخواست (پنل و مینی‌اپ)',
         'desc' => 'در ثبتِ دستیِ درخواستِ کارکنان در پنل، کنارِ نام‌ها دکمه‌ی «استعلامِ نام» و کنارِ کد پستی «استعلامِ کد پستی» آمد (دستی نوشتن همچنان آزاد است). در مینی‌اپِ ثبتِ درخواست، برای بیمه‌گذارِ غیر از خودِ کاربر، به محضِ واردکردنِ کد ملی و تاریخ تولد نام خودکار پر می‌شود و اگر نیامد دستی نوشته می‌شود؛ کنارِ کد پستی هم دکمه‌ی «استعلامِ کد پستی» هست. در تنظیماتِ استعلامات می‌شود استعلامِ کد پستی را برای کاربران اجباری کرد.'],
        ['id' => '140-x-portal-notif-hidden', 'type' => 'fix', 'area' => 'پنلِ شرکت‌ها', 'title' => 'پنجره‌ی اعلان‌ها در پنلِ شرکت‌ها دیده نمی‌شد',
         'desc' => 'با زدنِ زنگوله‌ی اعلان‌ها در پنلِ شرکت‌ها، پنجره زیرِ سربرگ بریده می‌شد و دیده نمی‌شد. حالا پنجره روی همه‌ی صفحه باز می‌شود (در پنلِ ما هم همین‌طور).'],
        ['id' => '140-f-company-portal-upload-opts', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'تنظیمِ بارگذاریِ مدارک برای هر شرکت',
         'desc' => 'در فرمِ هر شرکت (مدیریتِ شرکت‌ها) دو گزینه آمد: «می‌توانند مدارکِ کلی بفرستند» (چند فایل/زیپ/پوشه بدونِ ردیفِ مشخص؛ اگر خاموش باشد فقط بعد از ساختِ ردیف‌ها توسطِ شما، مدارکِ هر خودرو را در چک‌لیستِ همان خودرو می‌زنند) و «می‌توانند برای هر خودرو مدرکِ دیگر با نامِ دلخواه اضافه کنند». پیش‌فرضِ هر دو روشن است و رفتارِ شرکت‌های فعلی عوض نمی‌شود.'],
        ['id' => '140-i-docs-review-workspace', 'type' => 'improve', 'area' => 'شرکت‌ها', 'title' => 'میزِ تازه‌ی «بررسیِ مدارک»: فایل راست، فیلدها چپ، بعدی/قبلی',
         'desc' => 'پنجره‌ی تگ‌گذاری به میزِ بررسیِ تمام‌صفحه تبدیل شد: خودِ فایل بزرگ در سمتِ راست (عکس با بزرگ‌نمایی و چرخش، PDF با نمایشگرِ مرورگر) و فیلدها در سمتِ چپ. با «ثبت و بعدی» یا «رد کردن» مدرکِ بعدی همان‌جا باز می‌شود، «قبلی/بعدی» بدونِ ثبت جابه‌جا می‌کند (Alt+جهت‌ها، Ctrl+Enter برای ثبت) و شمارنده‌ی «چندم از چند» دارد. هر وقت ببندید، مدارکِ باقی‌مانده سرِ جایشان می‌مانند و با «شروعِ بررسی» در بالای فهرست ادامه می‌دهید.'],
        ['id' => '140-f-pdf-page-picker', 'type' => 'feature', 'area' => 'بارگذاری', 'title' => 'انتخابِ صفحه‌های PDF هنگامِ بارگذاری (به‌جای دکمه‌ی «جداسازی»)',
         'desc' => 'هر جای سایت که فایلِ PDFِ چندصفحه‌ای انتخاب شود، همه‌ی صفحه‌ها با پیش‌نمایش نشان داده می‌شود و فقط صفحه‌هایی که انتخاب می‌کنید فرستاده می‌شود (همه، هیچ‌کدام، برعکس و بزرگ‌نمایی هم دارد). دکمه‌های «جداسازی PDF» زیرِ مدارک برداشته شد. عکسِ HEICِ آیفون هم پیش از ارسال در خودِ مرورگر به JPG تبدیل می‌شود. همه‌ی این کارها در مرورگر انجام می‌شود و باری روی هاست نمی‌گذارد.'],
        ['id' => '140-f-bulk-docs-zip-folder', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'ارسالِ گروهیِ مدارک: زیپ، پوشه و چند فایل',
         'desc' => 'در «افزودن مدارک» پرتالِ شرکت و در جزئیاتِ درخواست در پنل، می‌شود چند فایل، فایلِ زیپ (حتی زیپِ تودرتو) یا یک پوشه را انتخاب کرد: همه‌ی فایل‌ها پوشه به پوشه بیرون می‌آیند، PDFهای چندصفحه‌ای صفحه‌به‌صفحه جدا و همه از ۱ تا N نام‌گذاری می‌شوند و با نوعِ پیش‌فرضِ «سایر مدارک» به «بررسی مدارک» می‌روند (نوعِ هر فایل یا همه را با هم می‌شود عوض کرد).'],
        ['id' => '140-f-bg-upload-progress', 'type' => 'feature', 'area' => 'بارگذاری', 'title' => 'ارسالِ مدارک در پس‌زمینه با نوارِ پیشرفت',
         'desc' => 'ارسالِ گروهیِ مدارک (پرتالِ شرکت و پنل) در پس‌زمینه انجام می‌شود: نشانگرِ کوچکی پایینِ صفحه درصد، تعدادِ فایل‌ها و وضعیتِ هر فایل را نشان می‌دهد، با بستنِ پنجره یا رفتن به بخشِ دیگر ادامه دارد، لغوِ باقی‌مانده دارد و اگر صفحه را ببندید هشدار می‌دهد. بعد از پایان، شناساییِ خودکار و «بررسی مدارک» شروع می‌شود.'],
        ['id' => '140-f-company-row-custom-doc', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => '«مدرکِ دیگر» با نامِ دلخواه برای هر ردیف',
         'desc' => 'در چک‌لیستِ هر ردیفِ درخواستِ شرکتی (پنل و پرتالِ شرکت) خانه‌ی «مدرکِ دیگر» آمد: نامِ مدرک (مثلاً گواهی‌نامه یا وکالت‌نامه) را می‌نویسید و فایل را می‌زنید؛ با همان نام در فهرست دیده می‌شود و در پوشه‌ی ردیف به شکلِ «(نامِ مدرک) پلاک» ذخیره می‌شود. چند مدرک هم می‌شود زد و اجباری نیست.'],
        ['id' => '140-x-ai-import-moto-plate', 'type' => 'fix', 'area' => 'شرکت‌ها', 'title' => 'پلاکِ موتورسیکلت در ورودِ ردیف‌ها با هوش مصنوعی و اکسل',
         'desc' => 'ردیف‌های موتورسیکلت در «ورودِ ردیف‌ها از نامه» خوانده نمی‌شدند. حالا پلاکِ موتور با فیلدهای moto_city (سه رقمِ کدِ شهر) و moto_number (پنج رقم)، به شکلِ «۵۸۳-۷۶۲۲۴» یا «ایران ۵۸۳ ۷۶۲۲۴»، و حتی وقتی هوش مصنوعی آن را در فیلدهای پلاکِ خودرو گذاشته باشد شناخته می‌شود. متنِ آماده برای هوش مصنوعی، نمونه‌ی JSON، فایلِ نمونه‌ی اکسل و ستون‌های «کد شهر موتور / شماره پلاک موتور» هم اضافه شد.'],
        ['id' => '140-f-chat-max-size-per-user', 'type' => 'feature', 'area' => 'گفتگو', 'title' => 'سقفِ حجمِ فایلِ گفتگو برای هر کاربر',
         'desc' => 'در فرمِ ویرایشِ هر کاربر (داخلی و کاربرِ شرکت) خانه‌ی «سقفِ حجمِ فایل در گفتگو» آمد: خالی = پیش‌فرض ۲۰ مگابایت، عددِ دلخواه به مگابایت، یا ۰ برای بستنِ فرستادنِ فایل. سقفِ آپلودِ خودِ هاست هم کنارش نوشته می‌شود و سقفِ کاربر از آن بیشتر نمی‌شود.'],
        ['id' => '140-i-pdf-engine-php', 'type' => 'improve', 'area' => 'تشخیصِ مدارک', 'title' => 'خواندن و پردازشِ PDF کاملاً با PHP، بدونِ پایتون',
         'desc' => 'همه‌ی کارهایی که با پایتون انجام می‌شد حالا با موتورِ PDFِ خودِ سایت (PHP) و با همان قاعده‌ها و همان خروجی انجام می‌شود: صدورِ گروهی و جدا کردنِ بیمه‌نامه‌های یک فایل، الحاقیه (تکی و گروهی)، پرسش‌نامه/پیشنهاد، معرفی‌نامه‌ی متنی، سندِ خودروی متنی، شناساییِ مدارکِ ربات، استخراجِ فیلدهای گزارشِ بازدید (پارسرهای اختصاصی به .php تبدیل شدند) و ابزارهای PDF (ادغام، جداسازی، فشرده‌سازی، چرخش، حذفِ صفحه). دیگر هیچ پروسه‌ی جداگانه‌ای روی هاست اجرا نمی‌شود که گیر کند و منابع را بگیرد. عکس‌ها و PDFهای اسکن‌شده خوانده نمی‌شوند و برای ورودِ دستی می‌مانند.'],
        ['id' => '140-x-upload-dotted-names', 'type' => 'fix', 'area' => 'بارگذاری', 'title' => 'پذیرفتنِ فایل‌هایی که در نامشان نقطه دارند',
         'desc' => 'فایل‌هایی مثلِ «اسکن ۲۵.۲.pdf» یا «..عکس.jpg» با پیامِ «فرمت معتبر نیست» رد می‌شدند. حالا فقط پسوندِ آخرِ نام ملاک است و این فایل‌ها در همه‌ی بارگذاری‌ها پذیرفته می‌شوند؛ فایل‌های خطرناک (مثلِ x.php.jpg) همچنان رد می‌شوند.'],
        ['id' => '140-f-devtools-guard', 'type' => 'feature', 'area' => 'امنیت', 'title' => 'بستنِ Inspect و کلیدهای ابزارِ توسعه‌دهنده',
         'desc' => 'در پنل، پرتالِ شرکت‌ها و مینی‌اپ کلیدهای F12، Ctrl+Shift+I/J/C، Ctrl+U (نمایشِ کد) و Ctrl+S (ذخیره‌ی صفحه) بسته شد و اگر ابزارِ توسعه‌دهنده باز شود صفحه پوشانده می‌شود. فایل‌های PHP هیچ‌وقت کدشان به مرورگر نمی‌رسد؛ Ctrl+S فقط HTMLِ خروجی را ذخیره می‌کرد. در «امنیت ← تنظیمات» قابلِ خاموش/روشن کردن است.'],
        ['id' => '140-x-sapi-otp-template-test', 'type' => 'fix', 'area' => 'تنظیمات', 'title' => 'آزمایشِ «پیامکی OTP» با همان قالبی که انتخاب شده',
         'desc' => 'در «کلیدهای API» دکمه‌ی «ارسالِ کدِ آزمایشی» تا حالا با قالبِ ذخیره‌شده می‌فرستاد، پس عوض کردنِ قالب بدونِ ذخیره در آزمایش اثری نداشت. حالا کد با قالبی که در فهرست انتخاب شده فرستاده می‌شود؛ شماره‌ی قالب در نتیجه نوشته می‌شود و «درخواستِ فرستاده‌شده» (کد، شماره، قالب) هم کنارِ پاسخِ خامِ s.api.ir دیده می‌شود.'],
        ['id' => '140-f-visit-appt-pick', 'type' => 'feature', 'area' => 'بازدیدِ خودرو', 'title' => 'انتخابِ نوبتِ بازدید در مینی‌اپ و بخشِ «نوبت‌های بازدید» در پنل',
         'desc' => 'بعد از بارگذاریِ مدارکِ بدنه پیامِ موفقیت می‌آید و کاربر یکی از نوبت‌های آزادِ هفته‌ی آینده را از روی تقویمِ کاری انتخاب می‌کند (روزها، ساعت‌ها و ظرفیت از «تنظیمات ← بازدید»؛ گزینه‌ی «انتخابِ نوبت توسطِ کاربر» و «بازه‌ی انتخاب»). در فهرستِ درخواست‌ها نوشته می‌شود صدور منوط به بازدید است و نوبتِ گرفته‌شده هم دیده می‌شود. در پنل، بخشِ «نوبت‌های بازدید» تقویمِ هفته به هفته، فهرستِ امروز/پیشِ رو/گذشته/انجام‌شده، جستجو، نوبتِ دستی (حتی خارج از برنامه، با پیام در ربات) و لغو دارد؛ نوبتِ هر درخواست در صفحه‌ی همان درخواست هم نشان داده می‌شود. صدورِ گزارشِ بازدیدِ وصل به درخواست، نوبت را «انجام شد» و بازدید را تأیید می‌کند و عکس‌ها و PDFِ گزارش در پوشه‌ی بایگانیِ درخواست ذخیره می‌شود.'],
        ['id' => '140-i-miniapp-visit-name', 'type' => 'improve', 'area' => 'مینی‌اپ', 'title' => '«بازدیدِ خودرو» به‌جای «بازدیدِ سلامت» در مینی‌اپ',
         'desc' => 'در همه‌ی متن‌های مینی‌اپ و پیام‌های مربوط به آن، «بازدیدِ سلامتِ خودرو» به «بازدیدِ خودرو» تغییر کرد. نامِ دکمه‌های ربات تغییری نکرد.'],
        ['id' => '140-f-api-keys-sapi', 'type' => 'feature', 'area' => 'تنظیمات', 'title' => 'کلیدهای API: کلید و تنظیماتِ هر وب‌سرویس (s.api.ir)',
         'desc' => 'در «تنظیمات ← کلیدهای API» (فقط مدیر کل) برای هر وب‌سرویس کلیدِ دسترسی و تنظیماتش وارد می‌شود: کلیدِ مشترکِ s.api.ir (آدرسِ پایه و زمانِ انتظار)، «پیامکی OTP» (کلید و قالبِ پیامک) و «استعلامِ شخصِ حقوقی». هر کدام دکمه‌ی آزمایش دارد (Echo رایگان، ارسالِ کدِ آزمایشی، استعلامِ آزمایشی) و پاسخِ سرویس نشان داده می‌شود. کلیدها در صفحه فقط با ۴ نویسه‌ی آخر دیده می‌شوند.'],
        ['id' => '140-f-otp-channels', 'type' => 'feature', 'area' => 'پیامک', 'title' => 'انتخابِ راهِ ارسالِ کدِ تأیید برای ربات و ورود به پنل',
         'desc' => 'در «پیامک و ورود با کدِ تأیید»: کدِ ورودِ کارکنان در ربات «غیرفعال / پنلِ پیامک / پیامکی OTP (s.api.ir)» و کدِ ورود به پنل «ربات بله / پنلِ پیامک / پیامکی OTP» انتخاب می‌شود. در صفحه‌ی ورود نوشته می‌شود کد از کدام راه و به کدام شماره (پوشیده) فرستاده شد. تنظیماتِ قبلی خودکار همان رفتارِ قبلی را دارد.'],
        ['id' => '140-f-company-inquiry', 'type' => 'feature', 'area' => 'شرکت‌ها', 'title' => 'استعلامِ مشخصاتِ ثبتیِ شرکت با شناسه‌ی ملی',
         'desc' => 'در فرمِ تعریف/ویرایشِ شرکت، بخشِ «مشخصاتِ ثبتی» آمد: با شناسه‌ی ملیِ ۱۱ رقمی و دکمه‌ی استعلام، نوعِ شرکت، شماره و تاریخِ ثبت، کدپستی، استان، شهر، آدرس و وضعیت (فعال/غیرفعال) پر می‌شود؛ نامِ شرکتِ موجود عوض نمی‌شود و فقط پیشنهاد داده می‌شود. اگر شرکتی با همان شناسه قبلاً تعریف شده باشد هشدار می‌دهد. همه‌ی خانه‌ها دستی هم قابلِ ورود است.'],
        ['id' => '140-f-recon-archive-visibility', 'type' => 'feature', 'area' => 'مغایرت‌گیری با پاسارگاد', 'title' => 'فهرستِ تازه‌ی مغایرت‌گیری‌ها، نمایش برای هر کاربر و پوشه‌ی بایگانی',
         'desc' => 'فهرستِ مغایرت‌گیری‌ها با جستجو، فیلترِ سال و ماه، باز/بسته و (برای مدیر) ثبت‌کننده، گروه‌بندی به تفکیکِ ماه، نوارِ پیشرفت و صفحه‌بندی بازطراحی شد. هر کاربر فقط مغایرت‌گیری‌های خودش را می‌بیند و مدیر کل همه را. برای هر مغایرت‌گیری پوشه‌ای در «بایگانی مغایرت‌گیری / سال / ماه سال / عنوان» ساخته می‌شود با فایل‌های ورودیِ بیمه‌گر، خروجی‌های اصلاح‌شده و اکسلِ فهرستِ مغایرت‌ها، که با هر تصمیم به‌روز می‌شود؛ با حذفِ مغایرت‌گیری، پوشه به «حذف‌شده / تاریخ» منتقل می‌شود. دکمه‌ی «پوشه‌ی بایگانی» آن را در مدیریتِ فایل باز می‌کند.'],
        ['id' => '140-i-recon-new-insurer-excel', 'type' => 'improve', 'area' => 'مغایرت‌گیری با پاسارگاد', 'title' => '«خروجیِ اکسلِ بیمه‌گرِ جدید» از همان بخشِ ورودِ اکسل',
