        ['id' => '140-i-recon-attach-src', 'type' => 'improve', 'area' => 'مغایرت‌گیری با پاسارگاد', 'title' => 'خروجیِ اصلاح‌شده برای مغایرت‌گیری‌های قبلی، بدونِ اجرای دوباره',
         'desc' => 'برای مغایرت‌گیری‌هایی که پیش از امکانِ «خروجیِ اصلاح‌شده» انجام شده‌اند (فایلِ اصلی‌شان نگه داشته نشده بود)، دکمه‌ی «بارگذاریِ فایلِ اصلیِ بیمه‌گر» آمد: همان اکسلی را که از پاسارگاد گرفته بودید بزنید تا به همان مغایرت‌گیری وصل شود؛ تصمیم‌های قبلی سرِ جایش می‌ماند و دکمه‌ی خروجیِ اصلاح‌شده ظاهر می‌شود. اگر فایل مربوط به آن مغایرت‌گیری نباشد پذیرفته نمی‌شود. دکمه‌ی «اکسل» هم برای جدا شدن از خروجیِ اصلاح‌شده «اکسلِ فهرستِ مغایرت‌ها» نام گرفت.'],
        ['id' => '140-x-vehicle-pride-peykan-group', 'type' => 'fix', 'area' => 'مینی‌اپ', 'title' => 'گروهِ جدا و نرخِ درست برای پراید و پیکان در فهرستِ خودروها',
