        ['id' => '140-i-contacts-import-duplicate', 'type' => 'improve', 'area' => 'بانک مخاطبین', 'title' => 'ورودِ اکسل: کد ملی و شماره‌ی تکراری «تکراری» شناخته می‌شود',
